fun {α} [BEq α] left right =>
  WellFounded.Nat.fix (fun x => Std.Slice.size left - x.size) fun pref a =>
    let i := pref.size;
    if x : i < Std.Slice.size left ∧ i < Std.Slice.size right then
      if h : (left[i] == right[i]) = true then a (pref.push left[i]) ⋯
      else (pref, left.drop pref.size, right.drop pref.size)
    else (pref, left.drop pref.size, right.drop pref.size)

